// Temporaere Bild-Bridge, nur zum Einspielen der Binaerdateien des
// Quizfunnels ins Repo. Wird direkt nach dem Lauf durch einen 410-Stub ersetzt.
const D = {
  "img/bernd.jpg": "",
  "img/haus-kachel.jpg": "",
  "img/mfh-a.jpg": "",
  "img/strasse-a.jpg": "",
  "og-sofortleads.jpg": "",
  "agb-2026-09-24.pdf": "",
  "fonts/manrope-latin.woff2": "",
  "fonts/manrope-latin-ext.woff2": "",
  "fonts/caveat-latin.woff2": "",
  "fonts/caveat-latin-ext.woff2": "",
};
const T = { jpg: "image/jpeg", pdf: "application/pdf", woff2: "font/woff2" };
exports.handler = async function (event) {
  const n = ((event && event.queryStringParameters) || {}).n || "";
  const b = D[n];
  if (!b) {
    return { statusCode: 404, headers: { "Content-Type": "text/plain" }, body: "unbekannt" };
  }
  const teile = n.split(".");
  const endung = teile[teile.length - 1];
  return {
    statusCode: 200,
    headers: { "Content-Type": T[endung] || "application/octet-stream", "Cache-Control": "no-store" },
    body: b,
    isBase64Encoded: true
  };
};
